const config = {
  flowVersion: 'sharepoint-rag-v4.2-image-chunkfix',
  embeddingModel: 'text-embedding-3-small',
  embeddingDimensions: 1536,
  chunkSize: 1600,
  chunkOverlap: 200,
  embeddingBatchSize: 50,
  mistralModel: 'mistral-ocr-latest',
  storageBucket: 'rag',
  storagePublicBase: 'https://zckaxkpycyyxaymmkmvu.supabase.co/storage/v1/object/public/rag/',
  defaultAudience: 'public',
  minBodyLength: 20,
  // Basis fuer die Dokument-URL.
  // Power Automate schickt nur den Pfad ab Bibliotheksebene, nie die Site.
  // Ohne diese Konstante bleibt sharepoint_url leer und ein Treffer ist
  // fuer den Anwender nicht anklickbar.
  sharePointSiteUrl: 'https://rwgrheinland.sharepoint.com/sites/rwgintranet'
};

return $input.all().map(item => ({
  json: { ...item.json, _config: config },
  binary: item.binary
}));

const item = $input.first();
const body = item.json?.body ?? item.json ?? {};
const config = item.json?._config ?? {};

function first(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return null;
}
function truthy(value) {
  if (value === true || value === 1) return true;
  const text = String(value ?? '').trim().toLowerCase();
  return ['true','1','yes','ja','deleted','remove','removed'].includes(text);
}
function normalizeAction(value) {
  return String(value ?? '').trim().toUpperCase().replace(/[\s.-]+/g, '_');
}

const rawAction = first(
  body.operation, body.action, body.event_type, body.eventType,
  body.change_type, body.changeType, body.event,
  item.json?.operation, item.json?.action
);

const action = normalizeAction(rawAction);
const deleteAliases = new Set(['DELETE','DELETED','REMOVE','REMOVED','FILE_DELETED','ITEM_DELETED','DELETE_FILE','DELETE_ITEM','HARD_DELETE']);
const insertAliases = new Set(['INSERT','CREATE','CREATED','ADD','ADDED','NEW','FILE_CREATED','ITEM_CREATED']);
const updateAliases = new Set(['UPDATE','UPDATED','MODIFY','MODIFIED','CHANGE','CHANGED','UPSERT','FILE_UPDATED','ITEM_UPDATED']);

let crud_intent = 'UPSERT';
if (truthy(body.deleted) || truthy(body.is_deleted) || truthy(body.isDeleted) || deleteAliases.has(action)) {
  crud_intent = 'DELETE';
} else if (insertAliases.has(action)) {
  crud_intent = 'INSERT';
} else if (updateAliases.has(action)) {
  crud_intent = 'UPDATE';
}

// ============================================================
// DATEIPFAD VEREINHEITLICHEN
//
// Power Automate liefert das Feld kleingeschrieben als 'filepath'.
// JavaScript ist case-sensitiv, 'filePath' greift also nicht.
// Ohne diese Zuordnung bleibt file_path leer und die Dokument-URL
// faellt auf die GUID-Variante zurueck oder wird gar nicht ableitbar.
//
// Der Pfad ist ausschliesslich Anzeige- und Verlinkungsinformation:
// - er kann sich aendern, wenn das Dokument verschoben wird
// - bei DELETE liefert SharePoint ihn nicht mehr, er ist dann leer
//
// Identifiziert wird deshalb nie ueber den Pfad, sondern immer ueber
// file_id / doc_id. Ein leerer Pfad darf keinen gespeicherten Wert
// ueberschreiben, deshalb bleibt er hier null statt Leerstring.
// ============================================================
const dateipfad = first(
  body.filepath, body.file_path, body.filePath,
  body.server_relative_url, body.serverRelativeUrl,
  body.path, body.relative_path
);

const vereinheitlichterBody = { ...body };
if (dateipfad !== null) {
  vereinheitlichterBody.file_path = String(dateipfad).trim();
}

// ============================================================
// SITE-BASIS ERGAENZEN
//
// Der Sender schickt den Pfad ab Bibliotheksebene, zum Beispiel
// 'Schulungen/Shared Documents/Markt Prozesse/Datei.docx', aber nie
// die Site selbst. Ohne Basis kann buildSharePointUrl nichts bauen
// und sharepoint_url bleibt null.
//
// Aufgefuellt wird nur, wenn der Sender nichts mitschickt. Liefert er
// eine Site oder eine absolute URL, hat diese Vorrang - so bleibt der
// Weg offen, spaeter mehrere Sites zu bedienen, ohne hier zu bauen.
// ============================================================
const siteVomSender = first(body.site_url, body.siteUrl, body.web, body.site);
const siteBasis = first(siteVomSender, config.sharePointSiteUrl);

if (siteBasis !== null) {
  vereinheitlichterBody.site_url = String(siteBasis).trim();
}

const site_basis_quelle = siteVomSender !== null
  ? 'uebergeben'
  : (siteBasis !== null ? 'config' : 'fehlt');

return [{
  json: {
    ...item.json,
    body: vereinheitlichterBody,
    _config: config,
    sharepoint_crud_intent: crud_intent,
    sharepoint_event_action: action || null,
    sharepoint_event_action_raw: rawAction ?? null,
    dateipfad_uebergeben: dateipfad !== null,
    site_basis_quelle,
    event_normalized_at: new Date().toISOString()
  },
  binary: item.binary
}];

const item = $input.first();
const body = item.json?.body ?? item.json ?? {};

function first(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return null;
}
function nullableString(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text || null;
}

const doc_id = nullableString(first(body.file_id, body.doc_id, body.id));
if (!doc_id) throw new Error('SHAREPOINT_DELETE_DOC_ID_MISSING');

return [{
  json: {
    doc_id,
    file_id: doc_id,
    filename: nullableString(first(body.filename, body.file_name)),
    file_path: nullableString(body.file_path),
    sharepoint_url: nullableString(first(body.sharepoint_url, body.webUrl, body.web_url)),
    event_action: item.json?.sharepoint_event_action || null,
    crud_action: 'DELETE',
    started_at: new Date().toISOString()
  }
}];

const ctx = $('Build Delete Context').first().json;
const sourceRaw = $('Get Delete SharePoint Source').first().json;
const source = Array.isArray(sourceRaw) ? (sourceRaw[0] || {}) : (sourceRaw || {});
const chunkRaw = $input.first().json;
const imageChunks = Array.isArray(chunkRaw) ? chunkRaw : (chunkRaw?.metadata ? [chunkRaw] : []);

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch { return []; }
  }
  return [];
}
function pathFromValue(value) {
  if (!value) return null;
  const raw = String(value).trim();
  if (!raw) return null;
  const markers = [
    '/storage/v1/object/public/rag/',
    '/storage/v1/object/sign/rag/',
    '/storage/v1/object/authenticated/rag/',
    '/storage/v1/object/rag/'
  ];
  for (const marker of markers) {
    const pos = raw.indexOf(marker);
    if (pos >= 0) {
      const path = raw.slice(pos + marker.length).split('?')[0];
      try { return decodeURIComponent(path); } catch { return path; }
    }
  }
  return raw.replace(/^\/+/, '');
}
function pathFromImage(image) {
  if (!image || typeof image !== 'object') return null;
  return pathFromValue(
    image.storage_path || image.storage_key || image.public_url || image.related_image_url || image.url || image.image_name
  );
}

const paths = new Set();
for (const image of parseJsonArray(source.images)) {
  const path = pathFromImage(image);
  if (path) paths.add(path);
}
for (const row of imageChunks) {
  const metadata = row?.metadata && typeof row.metadata === 'object' ? row.metadata : {};
  const path = pathFromImage(metadata);
  if (path) paths.add(path);
}

const storagePaths = Array.from(paths).filter(Boolean).sort();
const base = {
  doc_id: ctx.doc_id,
  source_found: Boolean(source.id),
  source_id: source.id || null,
  source_file_name: source.file_name || ctx.filename || null,
  planned_storage_delete_count: storagePaths.length
};

if (!storagePaths.length) {
  return [{ json: { ...base, has_storage_to_delete: false, storage_path: null } }];
}

return storagePaths.map(storage_path => ({
  json: {
    ...base,
    has_storage_to_delete: true,
    storage_path,
    storage_path_encoded: storage_path.split('/').map(segment => encodeURIComponent(segment)).join('/')
  }
}));

const item = $input.first();
const body = item.json?.body ?? item.json ?? {};
const config = item.json?._config ?? {};

function first(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return null;
}
function asArray(value) {
  if (Array.isArray(value)) return value.map(v => String(v).trim()).filter(Boolean);
  if (value === undefined || value === null || String(value).trim() === '') return [];
  return String(value).split(/[,;|]/).map(v => v.trim()).filter(Boolean);
}
function nullableString(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text ? text : null;
}
function encodePathSegments(path) {
  const raw = String(path || '');
  if (/%[0-9A-Fa-f]{2}/.test(raw)) return raw;
  return raw.split('/').map(seg => encodeURIComponent(seg)).join('/');
}
// Leitet die Dokument-URL ab, wenn der Sender sie nicht mitschickt.
// Reihenfolge: uebergeben > absoluter Pfad > Site+Pfad > Doc.aspx ueber GUID.
function buildSharePointUrl(supplied, siteUrl, filePath, docId, fileName) {
  const direct = nullableString(supplied);
  if (direct && /^https?:\/\//i.test(direct)) return { url: direct, quelle: 'uebergeben' };
  const site = nullableString(siteUrl);
  const path = nullableString(filePath);
  if (path && /^https?:\/\//i.test(path)) return { url: path, quelle: 'pfad_absolut' };
  if (site && path) {
    const origin = (site.match(/^https?:\/\/[^/]+/i) || [null])[0];
    if (path.startsWith('/') && origin) {
      return { url: origin + encodePathSegments(path), quelle: 'site_und_serverpfad' };
    }
    return { url: site.replace(/\/+$/, '') + '/' + encodePathSegments(path.replace(/^\/+/, '')), quelle: 'site_und_relativpfad' };
  }
  const guid = String(docId || '').replace(/[{}]/g, '');
  if (site && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(guid)) {
    return { url: site.replace(/\/+$/, '') + '/_layouts/15/Doc.aspx?sourcedoc=%7B' + guid + '%7D&file=' + encodeURIComponent(String(fileName || '')) + '&action=default', quelle: 'doc_aspx' };
  }
  return { url: null, quelle: 'nicht_ableitbar' };
}

const filename = String(first(body.filename, body.file_name, 'upload.bin'));
const doc_id = nullableString(first(body.file_id, body.doc_id));
const suppliedMime = nullableString(first(body.mimeType, body.mime_type));
const rawBase64 = String(first(body.fileBase64, body.file_base64, '') || '').trim();

if (!doc_id) throw new Error('SHAREPOINT_DOC_ID_MISSING');
if (!filename || filename === 'upload.bin') throw new Error('SHAREPOINT_FILENAME_MISSING');
if (!rawBase64) throw new Error('SHAREPOINT_FILE_BASE64_MISSING: ' + doc_id);

let fileBase64Clean = rawBase64
  .replace(/^data:.*?;base64,/i, '')
  .replace(/\s/g, '')
  .replace(/-/g, '+')
  .replace(/_/g, '/');

while (fileBase64Clean.length % 4) fileBase64Clean += '=';

let ext = (filename.split('.').pop() || '').toLowerCase();

const mimeByExt = {
  pdf:'application/pdf',
  docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  doc:'application/msword',
  pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  ppt:'application/vnd.ms-powerpoint',
  png:'image/png', jpg:'image/jpeg', jpeg:'image/jpeg',
  tif:'image/tiff', tiff:'image/tiff', webp:'image/webp', avif:'image/avif',
  csv:'text/csv',
  xls:'application/vnd.ms-excel',
  xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  xlsm:'application/vnd.ms-excel.sheet.macroEnabled.12',
  ods:'application/vnd.oasis.opendocument.spreadsheet',
  txt:'text/plain', md:'text/markdown', markdown:'text/markdown', log:'text/plain',
  json:'application/json', xml:'application/xml', html:'text/html', htm:'text/html',
  ics:'text/calendar', rtf:'application/rtf'
};

let mime_type = suppliedMime || mimeByExt[ext] || 'application/octet-stream';

const magic = fileBase64Clean.slice(0, 16);
if (magic.startsWith('JVBERi0')) {
  ext = 'pdf';
  mime_type = 'application/pdf';
} else if (magic.startsWith('iVBORw0')) {
  ext = 'png';
  mime_type = 'image/png';
} else if (magic.startsWith('/9j/')) {
  ext = 'jpg';
  mime_type = 'image/jpeg';
} else if (magic.startsWith('R0lGOD')) {
  ext = 'gif';
  mime_type = 'image/gif';
}

const documentAi = new Set(['pdf','docx','pptx','doc','ppt','png','jpg','jpeg','tif','tiff','webp','avif']);
const spreadsheet = new Set(['csv','xls','xlsx','xlsm','ods']);
const textLike = new Set(['txt','md','markdown','log','json','xml','html','htm','ics','rtf']);

let route_group = 'unsupported';
if (documentAi.has(ext)) route_group = 'document_ai';
else if (spreadsheet.has(ext)) route_group = 'spreadsheet';
else if (textLike.has(ext)) route_group = 'text';

const imageExts = new Set(['png','jpg','jpeg','tif','tiff','webp','avif']);
const mistral_document_type = imageExts.has(ext) ? 'image_url' : 'document_url';

// ============================================================
// DOKUMENT-URL
// Ohne URL ist ein Treffer fuer den Anwender nicht auffindbar.
// Deshalb mehrere Feldnamen akzeptieren und notfalls ableiten.
// ============================================================
const siteUrl = nullableString(first(body.site_url, body.siteUrl, body.web, body.site));
const filePath = nullableString(first(body.file_path, body.filePath, body.server_relative_url, body.serverRelativeUrl, body.path, body.relative_path));
const dokumentUrl = buildSharePointUrl(
  first(body.sharepoint_url, body.webUrl, body.web_url, body.file_url, body.fileUrl, body.link, body.url),
  siteUrl,
  filePath,
  doc_id,
  filename
);

const allowedAudience = new Set(['public','it_internal']);
const rawAudience = String(first(body.audience, body.rag_audience, '') || '').trim().toLowerCase();
const audience = allowedAudience.has(rawAudience)
  ? rawAudience
  : (allowedAudience.has(String(config.defaultAudience || '')) ? config.defaultAudience : 'it_internal');

return [{
  json: {
    ...item.json,
    filename,
    title: filename.replace(/\.[^/.]+$/, ''),
    doc_id,
    file_id: doc_id,
    ext,
    fileType: ext,
    mime_type,
    mimeType: mime_type,
    route_group,
    mistral_document_type,
    audience,
    fileBase64Clean,
    drive_id: nullableString(body.drive_id),
    site_id: nullableString(body.site_id),
    site_url: siteUrl,
    file_path: filePath,
    sharepoint_url: dokumentUrl.url,
    sharepoint_url_quelle: dokumentUrl.quelle,
    author_name: nullableString(first(body.author_name, body.author)),
    author_email: nullableString(body.author_email),
    last_modified_by: nullableString(body.last_modified_by),
    created_at_sp: nullableString(first(body.created_at_sp, body.created)),
    last_modified_sp: nullableString(first(body.last_modified_sp, body.last_modified, body.modified)),
    document_version: nullableString(first(body.document_version, body.version)),
    tags: asArray(body.tags),
    department: nullableString(first(body.department, body.dept)),
    language: nullableString(body.language) || 'de',
    sensitivity_label: nullableString(body.sensitivity_label),
    flow_version: config.flowVersion || 'sharepoint-rag-v4.0-audience',
    sharepoint_crud_intent: item.json?.sharepoint_crud_intent || 'UPSERT',
    sharepoint_event_action: item.json?.sharepoint_event_action || null,
    _config: config,
    normalized_at: new Date().toISOString()
  }
}];

const normalized = $('Normalize SharePoint Input').first().json;

return $input.all().map(item => ({
  json: { ...normalized },
  binary: item.binary
}));

const input = $('Normalize SharePoint Input').first().json;
const signed = $input.first().json;
const url = signed.url;

if (!url) throw new Error('MISTRAL_SIGNED_URL_MISSING');

const annotationSchema = {
  name: 'sharepoint_visual_annotation',
  description:
    'AUSSCHLIESSLICH AUF DEUTSCH. ' +
    'Beschreibe das visuelle Element sachlich und nur anhand sichtbar erkennbarer Inhalte. ' +
    'Keine Ursachen oder Loesungen erfinden. ' +
    'Keine Vermutungen ueber Systeme, Produkte oder Prozesse. ' +
    'Die gesamte Beschreibung soll kompakt bleiben und insgesamt moeglichst nicht mehr als 1200 Zeichen umfassen.',

  schema: {
    type: 'object',
    properties: {
      image_type: {
        type: 'string',
        description:
          'Art des visuellen Elements, z. B. Screenshot, Diagramm, Foto, Formular, UI oder Skizze. Maximal 100 Zeichen.'
      },

      short_description: {
        type: 'string',
        description:
          'Kurze deutsche Beschreibung der Kernaussage in maximal zwei Saetzen und maximal 250 Zeichen.'
      },

      detailed_description: {
        type: 'string',
        description:
          'Praezise und kompakte deutsche Beschreibung relevanter sichtbar erkennbarer Inhalte. ' +
          'Keine allgemeinen Erklaerungen, keine Vermutungen und keine Wiederholung der Kurzbeschreibung. ' +
          'Maximal 450 Zeichen.'
      },

      visible_text: {
        type: 'string',
        description:
          'Nur relevanter eindeutig sichtbarer Text, Fehlercodes, Bezeichnungen, Buttons, Felder und Werte. ' +
          'Nicht den gesamten Bildinhalt transkribieren. Nichts ergaenzen. Maximal 300 Zeichen. ' +
          'KEINE PERSONENBEZOGENEN DATEN uebernehmen: keine Klarnamen, Benutzernamen, Benutzer-IDs, ' +
          'Personalnummern, E-Mail-Adressen, Telefonnummern oder Unterschriften. ' +
          'Solche Angaben durch die Platzhalter [NAME], [BENUTZER-ID] oder [KONTAKT] ersetzen.'
      },

      document_relevance: {
        type: 'string',
        description:
          'Warum dieses Bild im Dokument relevant ist, nur soweit aus Dokument und Bild eindeutig ableitbar. ' +
          'Maximal ein Satz und maximal 150 Zeichen.'
      }
    },

    required: [
      'image_type',
      'short_description',
      'detailed_description',
      'visible_text',
      'document_relevance'
    ],

    additionalProperties: false
  },

  strict: true
};

const type = input.mistral_document_type;

const document = type === 'image_url'
  ? {
      type: 'image_url',
      image_url: url
    }
  : {
      type: 'document_url',
      document_url: url
    };

return [{
  json: {
    ocrBody: {
      model: input._config?.mistralModel || 'mistral-ocr-latest',
      document,
      table_format: 'markdown',
      bbox_annotation_format: {
        type: 'json_schema',
        json_schema: annotationSchema
      },
      include_image_base64: true
    }
  }
}];

const input = $('Normalize SharePoint Input').first().json;
const response = $input.first().json || {};
const pages = Array.isArray(response.pages) ? response.pages : [];

function safeObject(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return {};
    try {
      const parsed = JSON.parse(trimmed);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
      if (Array.isArray(parsed)) return { descriptions: parsed };
    } catch {}
    return { short_description: trimmed };
  }
  if (Array.isArray(value)) return { descriptions: value };
  return {};
}

function annotationText(annotation) {
  const a = safeObject(annotation);
  const parts = [];
  const fields = [
    ['Bildtyp', a.image_type],
    ['Kurzbeschreibung', a.short_description],
    ['Detailbeschreibung', a.detailed_description],
    ['Sichtbarer Text', a.visible_text],
    ['Dokumentbezug', a.document_relevance]
  ];
  for (const pair of fields) {
    const label = pair[0];
    const value = pair[1];
    if (value !== undefined && value !== null && String(value).trim()) {
      parts.push(label + ': ' + String(value).trim());
    }
  }
  if (Array.isArray(a.descriptions)) {
    const text = a.descriptions.map(v => String(v).trim()).filter(Boolean).join(' | ');
    if (text) parts.push('Beschreibung: ' + text);
  }
  return parts.join('\n') || 'Keine belastbare Bildbeschreibung vorhanden.';
}

function dataMime(dataUri, fallback) {
  const match = String(dataUri || '').match(/^data:([^;]+);base64,/i);
  return (match && match[1]) || fallback || 'image/png';
}
function dataBase64(dataUri) {
  return String(dataUri || '').replace(/^data:[^;]+;base64,/i, '').replace(/\s/g, '');
}

const rawImages = [];
const links = [];
const pageTexts = [];
const tableTexts = [];

for (const page of pages) {
  const pageIndex = Number.isInteger(page?.index) ? page.index : pageTexts.length;
  let markdown = String(page?.markdown || '');

  for (const link of (Array.isArray(page?.hyperlinks) ? page.hyperlinks : [])) {
    const normalized = typeof link === 'string' ? { url: link } : link;
    if (normalized && normalized.url) links.push({ page_index: pageIndex, ...normalized });
  }

  for (const image of (Array.isArray(page?.images) ? page.images : [])) {
    const id = String(image?.id || image?.name || ('page-' + pageIndex + '-image-' + rawImages.length));
    const annotation = safeObject(image?.image_annotation ?? image?.annotation);
    const annotation_text = annotationText(annotation);
    const imageBase64 = dataBase64(image?.image_base64);
    const mime = dataMime(image?.image_base64, 'image/png');

    if (imageBase64) {
      rawImages.push({
        page_index: pageIndex,
        mistral_image_id: id,
        image_base64_clean: imageBase64,
        image_mime: mime,
        annotation,
        annotation_text,
        origin: 'mistral_bbox'
      });
    }

    const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const placeholder = new RegExp('!?\\[[^\\]]*\\]\\(' + escaped + '\\)', 'g');
    // Im Fliesstext steht nur ein kurzer Verweis. Die vollstaendige Annotation
    // liegt im zugehoerigen image_attachment-Chunk. Frueher wurde der komplette
    // Annotationstext hier eingesetzt - dadurch lag er doppelt im Index und
    // verdraengte in bildlastigen Dokumenten den eigentlichen Dokumenttext.
    const verweisText = String(annotation.short_description || '').trim();
    const verweisTyp = String(annotation.image_type || 'Bild').trim();
    const verweis = verweisText
      ? '[VISUELLES ELEMENT ' + id + ' | ' + verweisTyp + ': ' + verweisText.slice(0, 200) + ']'
      : '[VISUELLES ELEMENT ' + id + ' | ' + verweisTyp + ']';

    markdown = markdown.replace(placeholder, '\n\n' + verweis + '\n');
  }

  for (const table of (Array.isArray(page?.tables) ? page.tables : [])) {
    const tableId = String(table?.id || ('page-' + pageIndex + '-table-' + tableTexts.length));
    const content = String(table?.content || '').trim();
    if (content) tableTexts.push('### ' + tableId + '\n' + content);
  }

  if (markdown.trim()) pageTexts.push('## Seite ' + (pageIndex + 1) + '\n' + markdown.trim());
}

