// ============================================================
// HARTER SPLIT: zerlegt einen zu langen Textblock zuverlaessig.
// Wird auch auf Absaetze angewendet, die laenger als chunkSize sind
// (OCR-Tabellen, Seiten ohne Leerzeile).
// ============================================================
function hardSplit(text, size, overlap) {
  const t = String(text || '');
  const parts = [];
  let start = 0;

  while (start < t.length) {
    const idealEnd = Math.min(start + size, t.length);
    let end = idealEnd;

    if (end < t.length) {
      const win = t.slice(start, idealEnd);
      const minKeep = Math.floor(size * 0.6);

      const candidates = [
        win.lastIndexOf('\n'),
        win.lastIndexOf('. '),
        win.lastIndexOf('! '),
        win.lastIndexOf('? '),
        win.lastIndexOf('; '),
        win.lastIndexOf(', '),
        win.lastIndexOf(' ')
      ].filter(i => i > minKeep);

      if (candidates.length) {
        end = start + Math.max(...candidates) + 1;
      }
    }

    const piece = t.slice(start, end).trim();

    if (piece) {
      parts.push(piece);
    }

    if (end >= t.length) {
      break;
    }

    start = Math.max(start + 1, end - overlap);
  }

  return parts;
}

function splitToChunks(text, chunkSize, overlap) {
  const normalized = String(text || '').trim();

  if (!normalized) {
    return [];
  }

  const size = Math.max(
    200,
    Number(chunkSize) || 1600
  );

  const ov = Math.min(
    Math.max(0, Number(overlap) || 0),
    Math.floor(size / 2)
  );

  // 1) Absaetze bilden.
  // Ueberlange Absaetze SOFORT hart splitten.
  const pieces = [];

  for (const raw of normalized.split(/\n\n+/)) {
    const p = raw.trim();

    if (!p) {
      continue;
    }

    if (p.length > size) {
      pieces.push(...hardSplit(p, size, ov));
    } else {
      pieces.push(p);
    }
  }

  // 2) Stuecke greedy zu Chunks packen, mit Overlap-Tail.
  const chunks = [];
  let current = '';

  for (const piece of pieces) {
    if (!current) {
      current = piece;
      continue;
    }

    if ((current + '\n\n' + piece).length <= size) {
      current += '\n\n' + piece;
      continue;
    }

    chunks.push(current.trim());

    // Overlap-Tail auf Wortgrenze ziehen. Ein roher slice(-ov) schneidet mitten
    // im Wort und laesst den Folge-Chunk mit einem Wortfragment beginnen.
    // Der Tail wird durch die Korrektur nur kuerzer, nie laenger.
    let tail = ov > 0
      ? current.slice(-ov)
      : '';

    if (tail) {
      const zeichenDavor = current.charAt(current.length - tail.length - 1);
      if (zeichenDavor && !/\s/.test(zeichenDavor)) {
        const luecke = tail.search(/\s/);
        tail = luecke === -1 ? '' : tail.slice(luecke + 1);
      }
      tail = tail.trimStart();
    }

    const seeded = tail
      ? tail + '\n\n' + piece
      : piece;

    current = seeded.length > size
      ? piece
      : seeded;
  }

  if (current.trim()) {
    chunks.push(current.trim());
  }

  // 3) Sicherheitsnetz.
  const result = [];

  for (const c of chunks) {
    if (c.length > size * 1.2) {
      result.push(...hardSplit(c, size, ov));
    } else {
      result.push(c);
    }
  }

  return result.filter(Boolean);
}

