const chunks = [];
let textIndex = 0;

const header = [
  '[SHAREPOINT] ' + ctx.filename,
  'Dokument-ID: ' + ctx.doc_id,
  'Format: ' + String(ctx.ext).toUpperCase(),
  ctx.file_path ? 'Pfad: ' + ctx.file_path : '',
  ctx.site_url ? 'Site: ' + ctx.site_url : '',
  ctx.department ? 'Bereich: ' + ctx.department : '',
  (ctx.tags && ctx.tags.length)
    ? 'Tags: ' + ctx.tags.join(', ')
    : '',
  ctx.sharepoint_url
    ? 'URL: ' + ctx.sharepoint_url
    : ''
].filter(Boolean).join('\n');

chunks.push({
  source_id: ctx.source_id,
  source_type: 'sharepoint',
  source_ref: ctx.source_ref,
  audience: AUDIENCE,
  chunk_index: textIndex++,
  chunk_text: header,
  token_count: estimateTokens(header),
  metadata: {
    ...baseMetadata,
    chunk_type: 'header'
  }
});

// ============================================================
// TEXT-CHUNKS
// ============================================================
const textParts = splitToChunks(
  ctx.content_text,
  CHUNK_SIZE,
  OVERLAP
);

for (const part of textParts) {
  const chunkText = (
    ctx.filename +
    '\n\n' +
    part
  ).trim();

  chunks.push({
    source_id: ctx.source_id,
    source_type: 'sharepoint',
    source_ref: ctx.source_ref,
    audience: AUDIENCE,
    chunk_index: textIndex++,
    chunk_text: chunkText,
    token_count: estimateTokens(chunkText),
    metadata: {
      ...baseMetadata,
      chunk_type: 'content',
      chunk_length: chunkText.length
    }
  });
}

// ============================================================
// BILD-CHUNKS
// Bildtexte ebenfalls mit der bestehenden Chunk-Logik teilen.
// Die Einzelfelder decken die Annotation bereits vollstaendig ab;
// annotation_text wiederholt exakt dieselben Felder und wird deshalb
// nicht zusaetzlich in den Chunktext aufgenommen.
// ============================================================
let imageChunkIndex = 100000;

for (const entry of images.entries()) {
  const index = entry[0];
  const image = entry[1];
  const annotation = image.annotation || {};

  const imageText = [
    '[SHAREPOINT-BILD] ' + ctx.filename,
    'Bild: ' + image.image_name,
    'Seite: ' + (Number(image.page_index || 0) + 1),
    'MIME: ' + (image.image_mime || ''),
    'Bildtyp: ' + (annotation.image_type || ''),
    'Kurzbeschreibung: ' + (annotation.short_description || ''),
    'Detailbeschreibung: ' + (annotation.detailed_description || ''),
    'Sichtbarer Text: ' + (annotation.visible_text || ''),
    'Dokumentbezug: ' + (annotation.document_relevance || ''),
    'Storage-Pfad: ' + (image.storage_path || ''),
    'Bild-URL: ' + (image.public_url || '')
  ]
    .filter(
      line =>
        !line.endsWith(': ') &&
        !line.endsWith(':\n')
    )
    .join('\n');

  const imageParts = splitToChunks(
    imageText,
    CHUNK_SIZE,
    OVERLAP
  );

  for (
    let partIndex = 0;
    partIndex < imageParts.length;
    partIndex++
  ) {
    const chunkText = imageParts[partIndex];

    chunks.push({
      source_id: ctx.source_id,
      source_type: 'sharepoint',
      source_ref: ctx.source_ref,
      audience: AUDIENCE,
      chunk_index: imageChunkIndex++,
      chunk_text: chunkText,
      token_count: estimateTokens(chunkText),

      metadata: {
        ...baseMetadata,
        chunk_type: 'image_attachment',
        image_name: image.image_name,
        storage_path: image.storage_path,
        related_image_url: image.public_url,
        annotation,
        annotation_text: image.annotation_text,
        image_mime: image.image_mime,
        image_index: index,
        image_part_index: partIndex,
        image_part_count: imageParts.length,
        page_index: image.page_index,
        mistral_image_id: image.mistral_image_id,
        origin: image.origin
      }
    });
  }
}

if (!chunks.length) {
  throw new Error('NO_SHAREPOINT_CHUNKS_CREATED');
}

const expected_chunk_indices = chunks
  .map(chunk => Number(chunk.chunk_index))
  .filter(Number.isInteger)
  .sort((a, b) => a - b);

return chunks.map(chunk => ({
  json: {
    ...chunk,
    current_images: images,
    expected_chunk_indices
  }
}));

