const allChunks = $input.all().map(item => item.json);
const ctx = $('Build Source Context').first().json;
const BATCH_SIZE = Number(ctx._config?.embeddingBatchSize || 50);

if (!allChunks.length) throw new Error('SHAREPOINT_CHUNK_BATCH_EMPTY');

