const decision = $('Decide Rebuild Or Skip').first().json;
const cleanup = $('Build Stale Chunk Cleanup Request').first().json;
const oldImages = Array.isArray(decision.existing_images) ? decision.existing_images : [];
const currentImages = Array.isArray(cleanup.current_images) ? cleanup.current_images : [];

function pathFromImage(image) {
  if (!image || typeof image !== 'object') return null;
  if (image.storage_path) return String(image.storage_path);
  if (image.storage_key) return String(image.storage_key);
  if (image.image_name) return String(image.image_name);
  if (image.public_url || image.url) {
    const raw = String(image.public_url || image.url);
    const marker = '/storage/v1/object/public/rag/';
    const pos = raw.indexOf(marker);
    if (pos >= 0) return decodeURIComponent(raw.slice(pos + marker.length));
  }
  return null;
}

const currentSet = new Set(currentImages.map(pathFromImage).filter(Boolean));
const stale = Array.from(new Set(oldImages.map(pathFromImage).filter(Boolean)))
  .filter(path => !currentSet.has(path));

if (!stale.length) {
  return [{ json: { has_stale_storage: false, storage_path: null, stale_storage_count: 0 } }];
}

return stale.map(path => ({
  json: {
    has_stale_storage: true,
    storage_path: path,
    storage_path_encoded: path.split('/').map(segment => encodeURIComponent(segment)).join('/'),
    stale_storage_count: stale.length
  }
}));

const ctx = $('Build Source Context').first().json;
