  images: current_images,
  links: Array.isArray(ctx.links) ? ctx.links : [],
  author_name: ctx.author_name,
  author_email: ctx.author_email,
  last_modified_by: ctx.last_modified_by,
  created_at_sp: ctx.created_at_sp,
  last_modified_sp: ctx.last_modified_sp,
  document_version: ctx.document_version,
  content_type: ctx.content_type,
  tags: ctx.tags || [],
  department: ctx.department,
  language: ctx.language || 'de',
  sensitivity_label: ctx.sensitivity_label,
  audience: ctx.audience === 'public' ? 'public' : 'it_internal',
  ingested_at: decision.existing?.ingested_at || now,
  last_ingested_at: now,
  ingestion_count: Number(decision.existing?.ingestion_count || 0) + 1
};

return [{ json: { row, storage_deleted_count } }];

const batch = $('Embedding Batch Loop').item.json;
const config = $('Config').first().json._config || {};
const expectedDimensions = Number(config.embeddingDimensions || 1536);
const response = $input.first().json || {};
const data = response.data || response.body?.data || [];
const chunks = batch.chunks || [];

if (!Array.isArray(data)) throw new Error('SHAREPOINT_EMBEDDING_RESPONSE_DATA_MISSING');
if (data.length !== chunks.length) {
  throw new Error('SHAREPOINT_EMBEDDING_COUNT_MISMATCH: expected=' + chunks.length + ', actual=' + data.length);
}

const embeddingByIndex = new Map();
for (const entry of data) {
  if (Number.isInteger(entry?.index) && Array.isArray(entry?.embedding)) {
    embeddingByIndex.set(entry.index, entry.embedding);
  }
}

const rows = chunks.map((chunk, index) => {
  const embedding = embeddingByIndex.get(index) || data[index]?.embedding || null;
  if (!Array.isArray(embedding)) throw new Error('SHAREPOINT_EMBEDDING_MISSING_AT_INDEX_' + index);
  if (embedding.length !== expectedDimensions) {
    throw new Error('SHAREPOINT_EMBEDDING_DIMENSION_MISMATCH_AT_' + index + ': ' + embedding.length);
  }
  return { ...chunk, embedding: '[' + embedding.join(',') + ']' };
});

return [{
  json: {
    rows,
    batch_number: batch.batch_number,
    batch_count: batch.batch_count,
    chunk_count: rows.length
  }
}];

const batch = $('Build Embedded Chunk Batch').item.json;

return [{
  json: {
    status: 'BATCH_WRITTEN',
    batch_number: batch.batch_number,
    batch_count: batch.batch_count,
    chunk_count: batch.chunk_count,
    written_at: new Date().toISOString()
  }
}];

const ctx = $('Build Source Context').first().json;
