  }
}];

// ============================================================
// STEUERUNG DES LAUFS
//
//   DELTA - stuendlich, nur was sich seit dem Anker geaendert hat.
//   ABGLEICH - naechtlich um 03:30 und bei jedem Handstart, voller
//   Vergleich des SharePoint-Bestands gegen die Wissensbasis.
// ============================================================
let laufart = 'delta';
try { if ($('Taeglich (Abgleich)').isExecuted) laufart = 'abgleich'; } catch (e) { laufart = 'delta'; }
// Der Modus statt des Triggers, weil n8n beim Handstart nicht den
// Manuellen Start nimmt, sondern den erstbesten Trigger im Flow.
try {
  const modus = String($execution.mode || '');
  if (modus === 'test' || modus === 'manual') laufart = 'abgleich';
} catch (e) {}
try { if ($('Manueller Start').isExecuted) laufart = 'abgleich'; } catch (e) {}

const steuerung = {
  laufart,

  driveId: 'b!C2yhEx592Ei36yvay6U9n6Opn9Rg7v1LnJCWDZ9ZCSJEbUEViC4mS52f5_kGkuq_',
  driveName: 'Documents (Shared Documents) der Untersite Schulungen',
  siteUrl: 'https://rwgrheinland.sharepoint.com/sites/rwgintranet/Schulungen',

  // Bilder, Videos, Verknuepfungen und Weblinks bleiben aussen vor -
  // sie machen zwei Drittel der Bibliothek aus, tragen aber keinen
  // durchsuchbaren Text.
  aktiveTypen: ['pdf', 'docx', 'doc', 'pptx', 'ppt', 'txt', 'csv', 'xlsx', 'xls', 'xlsm'],

  // Obergrenze je Lauf. Begrenzt wird sie nach oben durch die
  // 300-Sekunden-Grenze des Task-Runners je Code-Node.
  maxJeLauf: 3,

  // Namensfilter fuer gezielte Nacharbeit. Im Betrieb leer.
  nurDatei: '',

  verarbeiten: true,
  loeschungenMelden: true,
  zustandSchreiben: true,

  audience: 'public',
  maxDateiMb: 40,
  maxZeilenJeBlatt: 5000
};

// Word und PowerPoint gehen ueber die PDF-Wandlung von Graph in
// dieselbe OCR-Strecke wie die PDFs.
steuerung.ueberPdf = ['docx', 'doc', 'pptx', 'ppt'];

// Arbeitsmappen ueber die Workbook-API, weil der Extract-Node nur ein
// Blatt kennt und die uebrigen lautlos weglaesst.
steuerung.ueberWorkbook = ['xlsx', 'xlsm'];

steuerung.ankerIgnorieren = laufart === 'abgleich';

return [{ json: { _steuerung: steuerung } }];

// ============================================================
// WAS IST ZU TUN?
//
//   DELTA - Graph hat gefiltert. Was kommt, hat sich geaendert.
//   ABGLEICH - der volle Bestand wird gegen die Wissensbasis
//   gehalten. Vier Befunde: fehlend, unvollstaendig, veraltet,
//   verwaist.
//
// UNVOLLSTAENDIGE EINTRAEGE
// Der Ingest legt das Dokument an, bevor er die Chunks schreibt.
// Bricht ein Lauf dazwischen ab, bleibt ein Eintrag ohne Chunks
// stehen - in der Wissenssuche unsichtbar. Ohne diese Pruefung
// gaelte er als vorhanden und bliebe fuer immer leer.
//
// Antwortet die Chunk-Abfrage nicht, wird der Befund uebersprungen
// und alles Vorhandene als vollstaendig behandelt. Lieber eine
// Nacht spaeter nachgeholt als der ganze Abgleich blockiert.
//
// VORSICHT BEIM VERWAIST-BEFUND
// Als verwaist gilt nur, was eine Graph-Item-ID traegt und damit
// nachweislich aus dieser Bibliothek stammt. Dokumente aus der
// Power-Automate-Zeit bleiben unangetastet.
// ============================================================
const st = $('Steuerung').first().json._steuerung;
const aktiv = new Set(st.aktiveTypen.map(t => String(t).toLowerCase()));
const ueberPdf = new Set((st.ueberPdf || []).map(t => String(t).toLowerCase()));
const ueberWorkbook = new Set((st.ueberWorkbook || []).map(t => String(t).toLowerCase()));
const maxBytes = Number(st.maxDateiMb || 40) * 1048576;
const nurDatei = String(st.nurDatei || '').trim().toLowerCase();
const istAbgleich = st.laufart === 'abgleich';

const spNachId = {};
let deltaLink = null;
for (const s of $('SharePoint-Bestand').all()) {
  const b = s.json || {};
  for (const v of (b.value || [])) spNachId[String(v.id)] = v;
  if (b['@odata.deltaLink']) deltaLink = b['@odata.deltaLink'];
}
const spItems = Object.keys(spNachId).map(k => spNachId[k]);

// Entdoppelt: Der Seitenabruf kann dieselbe Seite mehrfach liefern,
// wenn der Knoten je Eingangsitem laeuft.
const ragNachId = {};
for (const i of $('Wissensbasis-Bestand').all()) {
  const d = i.json;
  if (d && d.doc_id) ragNachId[String(d.doc_id)] = d;
}
const ragDocs = Object.keys(ragNachId).map(k => ragNachId[k]);

// Chunkpruefung, sofern die Abfrage geantwortet hat
const mitChunks = {};
let chunkpruefung = false;
for (const i of $('Chunkzahlen laden').all()) {
  const ref = i.json && i.json.source_ref;
  if (ref) { mitChunks[String(ref)] = true; chunkpruefung = true; }
}

const ragNachName = {};
for (const d of ragDocs) {
  const n = String(d.file_name || '').toLowerCase();
  if (!n) continue;
  if (!ragNachName[n]) ragNachName[n] = [];
  ragNachName[n].push(d);
}
const istGraphKennung = (id) => /^01[A-Z0-9]{20,}$/.test(String(id || ''));

function endung(name) {
  const t = String(name || '').split('.');
  return t.length > 1 ? t.pop().toLowerCase() : '';
}
function ohneEndung(name) {
  const s = String(name || '');
  const i = s.lastIndexOf('.');
  return i > 0 ? s.slice(0, i) : s;
}
function pfadVon(it) {
  const p = (it.parentReference && it.parentReference.path) || '';
  const rein = p.replace(/^\/drives?\/[^/]+\/root:?/, '');
  return (rein ? decodeURIComponent(rein) : '') + '/' + it.name;
}
function bereichVon(pfad) {
  const teile = String(pfad || '').split('/').filter(Boolean);
  return teile.length > 1 ? teile[0] : null;
}

function aufgabeAus(it, grund) {
  const ext = endung(it.name);
  const pfad = pfadVon(it);
  const erst = (it.createdBy && it.createdBy.user) || {};
  const letzt = (it.lastModifiedBy && it.lastModifiedBy.user) || {};
  const istMappe = ueberWorkbook.has(ext);
  const gleichnamig = (ragNachName[String(it.name || '').toLowerCase()] || [])
    .filter(d => String(d.doc_id) !== String(it.id));

  return {
    aktion: istMappe ? 'tabelle' : 'datei',
    grund,
    item_id: it.id,
    drive_id: st.driveId,
    filename: it.name,
    uebergabe_name: istMappe ? (ohneEndung(it.name) + ' (' + ext + ', alle Blaetter).csv') : it.name,
    endung: ext,
    als_pdf: ueberPdf.has(ext),
    bytes: Number(it.size || 0),
    file_path: pfad,
    department: bereichVon(pfad),
    sharepoint_url: it.webUrl || null,
    author_name: erst.displayName || null,
    author_email: erst.email || null,
    last_modified_by: letzt.displayName || null,
    created_at_sp: it.createdDateTime || null,
    last_modified_sp: it.lastModifiedDateTime || null,
    etag: it.eTag || null,
    audience: st.audience,
    alt_doc_id: gleichnamig.length === 1 ? String(gleichnamig[0].doc_id) : null
  };
}

const aufgaben = [];
const gesehen = {};
const uebersprungen = { falscher_typ: 0, sperrdatei: 0, zu_gross: 0, namensfilter: 0, unveraendert: 0, limit_erreicht: 0 };
let geloeschtGemeldet = 0;
let unvollstaendig = 0;

const dateien = [];
const spIds = new Set();

for (const it of spItems) {
  if (it.deleted) {
    geloeschtGemeldet++;
    if (st.loeschungenMelden) {
      aufgaben.push({ aktion: 'loeschen', grund: 'in SharePoint geloescht', item_id: it.id, filename: it.name || null, drive_id: st.driveId });
    }
    continue;
  }
  if (!it.file) continue;
  dateien.push(it);
  spIds.add(String(it.id));
}

for (const it of dateien) {
  const ext = endung(it.name);
  gesehen[ext] = (gesehen[ext] || 0) + 1;
  if (!aktiv.has(ext)) { uebersprungen.falscher_typ++; continue; }
  // Office legt beim Oeffnen eine Sperrdatei mit Praefix ~$ an. Sie
  // traegt dieselbe Endung wie das Dokument, ist aber 162 Byte gross
  // und enthaelt nur den Namen des Bearbeiters. Ohne diesen Filter
  // laufen sie durch die OCR und landen als Leerdokumente im Bestand.
  if (String(it.name || '').indexOf('~$') === 0) { uebersprungen.sperrdatei++; continue; }
  if (nurDatei && String(it.name || '').toLowerCase().indexOf(nurDatei) === -1) { uebersprungen.namensfilter++; continue; }
  if (Number(it.size || 0) > maxBytes) { uebersprungen.zu_gross++; continue; }

  const imRag = ragNachId[String(it.id)];

  if (istAbgleich && imRag) {
    if (chunkpruefung && !mitChunks[String(it.id)]) {
      unvollstaendig++;
      aufgaben.push(aufgabeAus(it, 'im RAG ohne Chunks'));
      continue;
    }
    const spZeit = Date.parse(it.lastModifiedDateTime || 0) || 0;
    const ragZeit = Date.parse(imRag.last_ingested_at || 0) || 0;
    if (spZeit <= ragZeit) { uebersprungen.unveraendert++; continue; }
    aufgaben.push(aufgabeAus(it, 'in SharePoint neuer als im RAG'));
    continue;
  }

  aufgaben.push(aufgabeAus(it, istAbgleich ? 'fehlt in der Wissensbasis' : 'aus dem Delta'));
}

const verwaist = [];
let nichtZuordenbar = 0;
if (istAbgleich) {
  for (const d of ragDocs) {
    const id = String(d.doc_id);
    if (!istGraphKennung(id)) { nichtZuordenbar++; continue; }
    if (spIds.has(id)) continue;
    verwaist.push({ aktion: 'loeschen', grund: 'liegt nicht mehr in SharePoint', item_id: id, filename: d.file_name || null, drive_id: st.driveId });
  }
  const zuordenbar = ragDocs.length - nichtZuordenbar;
  if (zuordenbar > 0 && verwaist.length > Math.max(5, zuordenbar * 0.2)) {
    throw new Error('SICHERUNG: ' + verwaist.length + ' von ' + zuordenbar + ' zuordenbaren Dokumenten gaelten als verwaist. Abgleich abgebrochen.');
  }
  for (const v of verwaist) aufgaben.push(v);
}

// Unvollstaendige zuerst: Sie sind bereits angelegt und blockieren
// sonst dauerhaft einen Platz im Bestand.
const max = Number(st.maxJeLauf || 20);
const loeschen = aufgaben.filter(a => a.aktion === 'loeschen');
const luecken = aufgaben.filter(a => a.aktion !== 'loeschen' && a.grund === 'im RAG ohne Chunks');
const uebrige = aufgaben.filter(a => a.aktion !== 'loeschen' && a.grund !== 'im RAG ohne Chunks');
const einlesen = luecken.concat(uebrige);
if (einlesen.length > max) uebersprungen.limit_erreicht = einlesen.length - max;
const liste = loeschen.concat(einlesen.slice(0, max));

const formate = Object.keys(gesehen).sort((a, b) => gesehen[b] - gesehen[a]).map(e => e + ':' + gesehen[e]);

return [{ json: {
  _lauf: {
    laufart: st.laufart,
    items_im_bestand: spItems.length,
    dateien: dateien.length,
    rag_dokumente: ragDocs.length,
    chunkpruefung_moeglich: chunkpruefung,
    rag_mit_chunks: Object.keys(mitChunks).length,
    rag_nicht_zuordenbar: nichtZuordenbar,
    formate_gesehen: formate,
    geloescht_gemeldet: geloeschtGemeldet,
    verwaist_gefunden: verwaist.length,
    unvollstaendig_gefunden: unvollstaendig,
    fehlend_gesamt: einlesen.length,
    einzulesen: Math.min(einlesen.length, max),
    zu_loeschen: loeschen.length,
    aufgaben_gesamt: liste.length,
    uebersprungen,
    delta_link: deltaLink,
    delta_link_erhalten: !!deltaLink,
    vollabruf: !!st.ankerIgnorieren
  },
  aufgaben: liste
} }];

// Setzt genau die Felder, die der Webhook frueher von Power Automate
// bekam. Normalize SharePoint Event nimmt sie unveraendert an.
const st = $('Steuerung').first().json._steuerung;
const a = $('Je Aufgabe').first().json;
const b64 = $input.first().json.fileBase64;

if (!b64) {
  return [{ json: { _uebersprungen: 'KEIN_INHALT', filename: a.filename, item_id: a.item_id } }];
}

return [{ json: {
  operation: 'UPDATE',
  file_id: a.item_id,
  filename: a.uebergabe_name || a.filename,
  fileBase64: b64,
  filepath: a.file_path,
  site_url: st.siteUrl,
  sharepoint_url: a.sharepoint_url,
  drive_id: a.drive_id,
  author_name: a.author_name,
  author_email: a.author_email,
  last_modified_by: a.last_modified_by,
  created_at_sp: a.created_at_sp,
  last_modified_sp: a.last_modified_sp,
  department: a.department,
  document_version: a.etag,
  language: 'de',
  audience: a.audience,
  quelle: 'delta-' + st.laufart,
  original_extension: a.endung,
  ueber_pdf_gewandelt: !!a.als_pdf
} }];

// Jedes Blatt wird ein eigenes Item, damit der folgende Abruf je
// Blatt einmal laeuft. Ausgeblendete Blaetter bleiben aussen vor -
// sie sind bewusst versteckt.
const antwort = $input.first().json || {};
const a = $('Je Aufgabe').first().json;

if (antwort.error || !antwort.value) {
  const grund = antwort.error ? String(antwort.error.message || antwort.error).slice(0, 160) : 'KEINE_ANTWORT';
  return [{ json: Object.assign({}, a, { blatt: null, blatt_fehler: grund, blaetter_gesamt: 0, blatt_index: 0 }) }];
}

const alle = antwort.value || [];
const sichtbar = alle.filter(w => !w.visibility || w.visibility === 'Visible');

if (!sichtbar.length) {
  return [{ json: Object.assign({}, a, { blatt: null, blatt_fehler: 'KEINE_SICHTBAREN_BLAETTER', blaetter_gesamt: 0, blatt_index: 0 }) }];
}

return sichtbar
  .sort((x, y) => Number(x.position || 0) - Number(y.position || 0))
  .map((w, i) => ({ json: Object.assign({}, a, {
    blatt: w.name,
    blatt_index: i,
    blaetter_gesamt: sichtbar.length,
    blaetter_alle: alle.length,
    blatt_fehler: null
  }) }));

// Der Loeschzweig braucht nur die Kennung und die Absicht - keinen
// Dateiinhalt, den es ja auch nicht mehr gibt.
const a = $input.first().json;
return [{ json: {
  operation: 'DELETE',
  deleted: true,
  file_id: a.item_id,
  filename: a.filename,
  drive_id: a.drive_id,
  quelle: 'delta-leser'
} }];

// ============================================================
// ARBEITSMAPPE AUFBEREITEN
//
// Nicht jedes Blatt einer Arbeitsmappe ist eine Tabelle. Es gibt
// Deckblaetter, Notizen, ausgefuellte Formulare und Layouts. Wer
// dort blind die erste Zeile als Kopfzeile nimmt, erzeugt Unsinn.
//
// Und selbst echte Tabellen fangen selten in Zeile 1 an. Ueber der
// Kopfzeile stehen Titel, Stand-Angaben oder Leerzeilen. Deshalb
// wird die Kopfzeile in den ersten Zeilen gesucht statt angenommen.
//
// Tabellenblaetter kommen mit ihren echten Spalten, alles andere als
// Text unter Blatt, Zeile und Inhalt. Beides landet in derselben
// CSV, damit eine Datei ein Dokument bleibt.
// ============================================================
const st = $('Steuerung').first().json._steuerung;
const a = $('Je Aufgabe').first().json;
const maxZeilen = Number(st.maxZeilenJeBlatt || 5000);
const SUCHTIEFE = 8;

function text(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function istZahl(v) {
  const s = text(v);
  return s !== '' && !isNaN(Number(s.replace(/\./g, '').replace(',', '.')));
}

function kopfGuete(werte, i) {
  const zeile = werte[i] || [];
  const gefuellt = zeile.filter(c => text(c) !== '');
  if (gefuellt.length < 2) return 0;
  const zahlanteil = gefuellt.filter(istZahl).length / gefuellt.length;
  if (zahlanteil > 0.5) return 0;
  const eindeutig = new Set(gefuellt.map(c => text(c).toLowerCase())).size;
  if (eindeutig < gefuellt.length * 0.8) return 0;
  if (gefuellt.filter(c => text(c).length > 120).length) return 0;
  const probe = werte.slice(i + 1, i + 21);
  if (probe.length < 2) return 0;
  const schnitt = probe.reduce((s, z) => s + z.filter(c => text(c) !== '').length, 0) / probe.length;
  if (schnitt / gefuellt.length < 0.3) return 0;
  return gefuellt.length * Math.min(schnitt / gefuellt.length, 1) * 100 - i;
}

const eingang = $input.all();
const tabellen = [];
const notizen = [];
const hinweise = [];

for (let i = 0; i < eingang.length; i++) {
  const j = eingang[i].json || {};
  const meta = $('Blaetter auffaechern').all()[i];
  const name = (meta && meta.json.blatt) || j.blatt || ('Blatt ' + (i + 1));

  if (meta && meta.json.blatt_fehler) { hinweise.push(name + ': ' + meta.json.blatt_fehler); continue; }
  if (j.error) { hinweise.push(name + ': ' + String(j.error.message || j.error).slice(0, 120)); continue; }

  const alle = Array.isArray(j.values) ? j.values : [];
  const werte = alle.filter(z => z.some(c => text(c) !== ''));
  if (!werte.length) { hinweise.push(name + ': leer'); continue; }
  if (werte.length > maxZeilen + 1) hinweise.push(name + ': auf ' + maxZeilen + ' von ' + (werte.length - 1) + ' Zeilen begrenzt');

  let besteZeile = -1;
  let besteGuete = 0;
  for (let k = 0; k < Math.min(SUCHTIEFE, werte.length - 2); k++) {
    const g = kopfGuete(werte, k);
    if (g > besteGuete) { besteGuete = g; besteZeile = k; }
  }

  if (besteZeile >= 0) {
    const kopf = werte[besteZeile].map((c, k) => text(c) || ('Spalte ' + (k + 1)));
    const davor = werte.slice(0, besteZeile)
      .map((z, k) => ({ nr: k + 1, inhalt: z.map(text).filter(Boolean).join('  |  ') }))
      .filter(z => z.inhalt);
    if (davor.length) notizen.push({ name: name + ' (Kopfbereich)', zeilen: davor });
    if (besteZeile > 0) hinweise.push(name + ': Kopfzeile in Zeile ' + (besteZeile + 1) + ' gefunden');
    tabellen.push({ name, kopf, zeilen: werte.slice(besteZeile + 1, besteZeile + 1 + maxZeilen) });
  } else {
    const zeilen = werte.slice(0, maxZeilen).map((z, k) => ({
      nr: k + 1,
      inhalt: z.map(text).filter(Boolean).join('  |  ')
    })).filter(z => z.inhalt);
    if (zeilen.length) {
      notizen.push({ name, zeilen });
      hinweise.push(name + ': als Text uebernommen, keine Tabellenstruktur erkannt');
    }
  }
}

if (!tabellen.length && !notizen.length) {
  return [{ json: { _uebersprungen: 'KEINE_BLATTDATEN', filename: a.filename, item_id: a.item_id, hinweise } }];
}

const spalten = [];
const bekannt = new Set();
for (const b of tabellen) {
  for (const s of b.kopf) { if (!bekannt.has(s)) { bekannt.add(s); spalten.push(s); } }
}
if (notizen.length) {
  for (const s of ['Zeile', 'Inhalt']) { if (!bekannt.has(s)) { bekannt.add(s); spalten.push(s); } }
}

function feld(v) {
  const t = v === null || v === undefined ? '' : String(v);
  return /[",\n\r]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t;
}

const ausgabe = [['Blatt'].concat(spalten).map(feld).join(',')];
let zeilenTabelle = 0;
let zeilenText = 0;

for (const b of tabellen) {
  const nachSpalte = {};
  b.kopf.forEach((s, k) => { if (nachSpalte[s] === undefined) nachSpalte[s] = k; });
  for (const z of b.zeilen) {
    if (!z.some(c => text(c) !== '')) continue;
    const reihe = [b.name].concat(spalten.map(s => {
      const k = nachSpalte[s];
      return k === undefined ? '' : z[k];
    }));
    ausgabe.push(reihe.map(feld).join(','));
    zeilenTabelle++;
  }
}

for (const b of notizen) {
  for (const z of b.zeilen) {
    const reihe = [b.name].concat(spalten.map(s => {
      if (s === 'Zeile') return z.nr;
      if (s === 'Inhalt') return z.inhalt;
      return '';
    }));
    ausgabe.push(reihe.map(feld).join(','));
    zeilenText++;
  }
}

const csv = ausgabe.join('\n');
const art = tabellen.length && notizen.length ? 'Tabellen und Text'
          : tabellen.length ? 'alle Blaetter'
          : 'als Text';
const basis = String(a.uebergabe_name || '').replace(/ \([^)]*\)\.csv$/, '');

return [{ json: {
  operation: 'UPDATE',
  file_id: a.item_id,
  filename: basis + ' (' + a.endung + ', ' + art + ').csv',
  fileBase64: Buffer.from(csv, 'utf8').toString('base64'),
  filepath: a.file_path,
  site_url: st.siteUrl,
  sharepoint_url: a.sharepoint_url,
  drive_id: a.drive_id,
  author_name: a.author_name,
  author_email: a.author_email,
  last_modified_by: a.last_modified_by,
  created_at_sp: a.created_at_sp,
  last_modified_sp: a.last_modified_sp,
  department: a.department,
  document_version: a.etag,
  language: 'de',
  audience: a.audience,
  quelle: 'delta-' + st.laufart,
  original_extension: a.endung,
  ueber_pdf_gewandelt: false,
  _blaetter_tabelle: tabellen.map(b => b.name),
  _blaetter_text: notizen.map(b => b.name),
  _zeilen_tabelle: zeilenTabelle,
  _zeilen_text: zeilenText,
  _hinweise: hinweise
} }];

const st = $('Steuerung').first().json._steuerung;
const lauf = $('Aufgaben bestimmen').first().json._lauf;
return [{ json: {
  drive_id: st.driveId,
  drive_name: st.driveName,
  delta_link: lauf.delta_link,
  letzte_items: lauf.items_im_bestand,
  letzte_uebergeben: lauf.aufgaben_gesamt
} }];

// In einer splitInBatches-Schleife liefert $('Node').all() nur den
// letzten Durchlauf. Der zweite Parameter ist der Durchlaufindex; er
// wird hochgezaehlt, bis kein Durchlauf mehr kommt.
function sammle(name) {
  const raus = [];
  for (let i = 0; i < 2000; i++) {
    let items;
    try { items = $(name).all(0, i); } catch (e) { break; }
    if (!items || !items.length) break;
    for (const it of items) raus.push(it.json || {});
  }
  return raus;
}

const st = $('Steuerung').first().json._steuerung;
const lauf = $('Aufgaben bestimmen').first().json._lauf || {};
const aufgaben = $('Aufgaben bestimmen').first().json.aufgaben || [];

const eingelesen = sammle('Workflow Summary');
const geloescht = sammle('Delete Workflow Summary');
const unveraendert = sammle('No Change Summary');
// Ein zurueckgestellter Dienstausfall ist kein Dokumentfehler - er wird
// getrennt gezaehlt, damit die Fehlerzahl aussagekraeftig bleibt.
const fehlerAlle = sammle('Ingest Error Summary');
const zurueckgestellt = fehlerAlle.filter(j => j.zurueckgestellt);
const fehler = fehlerAlle.filter(j => !j.zurueckgestellt);
const uebersprungen = sammle('Uebergabe Datei').concat(sammle('Tabelle als CSV bauen')).filter(j => j._uebersprungen);
const mappen = sammle('Tabelle als CSV bauen').filter(j => !j._uebersprungen);

return [{ json: {
  laufart: lauf.laufart,
  bibliothek: st.driveName,

  gesehen: {
    items_im_bestand: lauf.items_im_bestand,
    dateien: lauf.dateien,
    rag_dokumente: lauf.rag_dokumente,
    rag_nicht_zuordenbar: lauf.rag_nicht_zuordenbar,
    formate: lauf.formate_gesehen
  },

  geplant: {
    einzulesen: lauf.einzulesen,
    zu_loeschen: lauf.zu_loeschen,
    verwaist_gefunden: lauf.verwaist_gefunden,
    geloescht_gemeldet: lauf.geloescht_gemeldet,
    uebersprungen: lauf.uebersprungen
  },

  ergebnis: {
    neu_oder_geaendert: eingelesen.length,
    unveraendert: unveraendert.length,
    geloescht: geloescht.length,
    uebersprungen: uebersprungen.length,
    zurueckgestellt: zurueckgestellt.length,
    fehler: fehler.length
  },

  woerter_eingelesen: eingelesen.reduce((s, j) => s + (Number(j.word_count) || 0), 0),
  chunks_geschrieben: eingelesen.reduce((s, j) => s + (Number(j.expected_chunk_count) || 0), 0),
  bilder_erkannt: eingelesen.reduce((s, j) => s + (Number(j.image_count) || 0), 0),

  arbeitsmappen: mappen.map(m => ({
    datei: m.filename,
    als_tabelle: m._blaetter_tabelle,
    als_text: m._blaetter_text,
    zeilen: (Number(m._zeilen_tabelle) || 0) + (Number(m._zeilen_text) || 0)
  })),

  uebersprungene: uebersprungen.map(j => (j.filename || j.item_id) + ': ' + j._uebersprungen),
  zurueckgestellte: zurueckgestellt.slice(0, 20).map(j => (j.filename || j.doc_id || '?') + ': ' + (j.error_code || j.status)),
  fehlerdetails: fehler.slice(0, 10).map(j => String(j.error_code || j.message || JSON.stringify(j)).slice(0, 160)),

  anker_geschrieben: !!st.zustandSchreiben && !!lauf.delta_link_erhalten,
  aufgabenliste: aufgaben.slice(0, 40).map(a => a.aktion + ' | ' + (a.grund || '-') + ' | ' + (a.filename || a.item_id))
} }];

// Faellt ein Aufruf der OCR-Strecke aus, wird die Aufgabe zurueckgestellt,
// statt den ganzen Lauf zu reissen. Die Schleife laeuft weiter, die
// Laufbilanz entsteht, und der Delta-Anker wird fortgeschrieben.
//
// Uebernommen wird ausschliesslich die Fehlermeldung, der Knotenname und
// der HTTP-Code. Das Rohobjekt bleibt aussen vor - n8n legt darin bei
// HTTP-Fehlern das komplette Request-Objekt samt Zugangsdaten ab.
const roh = $input.first().json || {};
const fehler = roh.error || roh;

const nachricht = String(fehler.message || roh.message || 'unbekannter Fehler');
const httpCode = String(fehler.httpCode || roh.httpCode || '');
// Der Fehlerausgang liefert weder Knotennamen noch HTTP-Code mit -
// gemessen in Lauf 111419. Verlaesslich ist nur $prevNode.
let knoten = (fehler.node && fehler.node.name) || '';
if (!knoten) { try { knoten = $prevNode.name; } catch (e) {} }
if (!knoten) knoten = 'Mistral';

let einordnung = 'DIENST_GESTOERT';
if (httpCode === '402' || /payment required/i.test(nachricht)) einordnung = 'KONTINGENT_ERSCHOEPFT';
else if (httpCode === '429') einordnung = 'RATE_LIMIT';
else if (httpCode === '401' || httpCode === '403') einordnung = 'ZUGANG';
else if (/ECONNRESET|socket hang up|closed unexpectedly/i.test(nachricht)) einordnung = 'KONTINGENT_ERSCHOEPFT';

let input = {};
try { input = $('Normalize SharePoint Input').first().json || {}; } catch (e) {}

const now = new Date().toISOString();
const kennung = einordnung + ' an ' + knoten + (httpCode ? ' (HTTP ' + httpCode + ')' : '');

return [{
  json: {
    error_row: {
      source_type: 'sharepoint',
      source_ref: input.doc_id || null,
      workflow_step: knoten,
      error_type: einordnung,
      error_message: 'OCR-Strecke nicht verfuegbar: ' + nachricht.slice(0, 300),
      error_detail: {
        filename: input.filename || null,
        extension: input.ext || null,
        http_code: httpCode || null,
        node: knoten
      },
      retry_count: 0,
      max_retries: 0,
      next_retry_at: null,
      resolved_at: null,
      resolved_by: null,
      raw_payload: {
        doc_id: input.doc_id || null,
        filename: input.filename || null,
        file_path: input.file_path || null,
        sharepoint_url: input.sharepoint_url || null
      },
      created_at: now
    },
    summary: {
      ok: false,
      zurueckgestellt: true,
      status: 'DEFERRED_' + einordnung,
      error_code: kennung,
      doc_id: input.doc_id || null,
      filename: input.filename || null,
      finished_at: now
    }
  }
}];
